#!/bin/bash
# Final encode (runs on the Mac mini): PNG frames + synthesised audio -> phone-like H.264 MP4.
# Metadata states plainly that this is rendered, not filmed. No camera make/model tags are written.
set -euo pipefail
EP1=${EP1:-$(cd "$(dirname "$0")/.." && pwd)}
FF=${FF:-ffmpeg}
OUT=${OUT:-$EP1/out/shishiqiushi.mp4}
mkdir -p "$(dirname "$OUT")"
NOTE='Rendered, not filmed. Computer-generated simulation of phone recordings of a laptop screen. The chat UI frames were captured from OpenCode driven by a scripted mock model server; every reply, tool call and error shown was written in advance, not generated by a model or returned by any real API. "Mythos 10" and the effort "Ululululultra" are fictional (the cost in the usage tooltip is what OpenCode computed from made-up per-token prices set for that fictional model; no money was spent); the web pages fetched on screen were local stub pages. The shell commands shown (caffeinate, pmset) ran against stand-in scripts that change nothing; the battery text is scripted. The "computer" tool calls only logged their input and controlled nothing: the Spotlight and Maps picture in that scene is a separate real screen recording of macOS (map search near the West Bund, Shanghai; listing as shown on 2026-10-30), cropped, moved and composited onto the rendered screen, and the pointer there is drawn. The pinyin candidate windows are real macOS screenshots (one per typing state) laid over the captured page, and the titlebar status icon is cut from a screenshot of the OpenCode app. Sound is synthesised, except the lighter, cigarette draw, exhale and the dawn birdsong outside the window, which are CC0 (public domain) recordings by Joseph Sardin, BigSoundBank.com. / 渲染生成，非拍摄：模拟手机对屏录像的计算机生成画面；界面来自由脚本化模拟服务驱动的 OpenCode，所有回复、工具调用和报错均为预先写定，并非模型生成或真实接口返回；“Mythos 10”与“Ululululultra”为虚构（用量提示中的成本是 OpenCode 按为该虚构模型设定的假单价计算的，并未产生任何费用）；画面中抓取的网页是本地占位页；画面中的命令行（caffeinate、pmset）运行的是不做任何改动的替身脚本，电量文字为写定；“computer”工具调用只记录参数、未控制任何东西：该场景的聚焦搜索与地图画面是另行真实录制的 macOS 屏幕（上海西岸附近的地图搜索，店铺信息为 2026-10-30 所见），经裁切、移位后合成到渲染屏幕上，其中的指针为绘制；拼音候选框是真实 macOS 截图（每个输入状态一张）叠加到抓取页面上，标题栏状态图标取自 OpenCode 应用截图；声音为合成，其中打火机、吸烟、吐气以及窗外清晨鸟叫为 BigSoundBank（Joseph Sardin）的 CC0 公有领域录音。'
if [ "${MUSIC:-1}" = "1" ]; then   # set MUSIC=0 if audio.wav was made with MUSIC=0 (render/sound.py)
  NOTE="$NOTE Music: J. S. Bach, Goldberg Variations BWV 988 (Aria; Variation 16), note data from the Mutopia Project editions (CC BY-SA 3.0); no pianist: the notes were performed by a script with timing fitted to the cut and rendered with the Spectrasonics Keyscape piano sample library. / 配乐：J. S. 巴赫《哥德堡变奏曲》BWV 988（咏叹调、第 16 变奏），音符数据来自 Mutopia Project 版本（CC BY-SA 3.0）；无人演奏：由脚本按剪辑时间演奏，用 Spectrasonics Keyscape 钢琴采样渲染。"
fi
SRC=(-framerate 30 -start_number 0 -i "$EP1/build/frames/f_%05d.png")
if [ "${PHONE_GEN:-1}" = "1" ]; then
  # generation 1 = what the phone would have written: HEVC ~10 Mbit/s, 1 s GOP, every clip
  # (a separate recording) starts on a keyframe. Moire/fine detail is what the codec loses first.
  # The deliverable below is then a transcode of it (like any uploaded phone video).
  CUTS=$(cd "$EP1" && "${PY:-$EP1/venv/bin/python3}" -c "import sys; sys.path.insert(0,'render'); import camera; print(','.join(f'{c.t0:.4f}' for c in camera.RIG.clips))")
  GEN1="$EP1/build/phone_gen1.mov"
  "$FF" -hide_banner -y "${SRC[@]}" \
    -vf "scale=out_color_matrix=bt709:out_range=tv:flags=lanczos+accurate_rnd,format=yuv420p" \
    -c:v libx265 -preset medium -tag:v hvc1 -b:v 10M -maxrate 12M -bufsize 20M \
    -x265-params "keyint=30:min-keyint=1:scenecut=0:log-level=error" -force_key_frames "$CUTS" \
    -colorspace bt709 -color_primaries bt709 -color_trc bt709 -color_range tv -an "$GEN1"
  SRC=(-i "$GEN1")
fi
"$FF" -hide_banner -y \
  "${SRC[@]}" \
  -i "$EP1/build/audio.wav" \
  -map 0:v -map 1:a \
  -vf "scale=out_color_matrix=bt709:out_range=tv:flags=lanczos+accurate_rnd,format=yuv420p" \
  -c:v libx264 -profile:v high -level 4.2 -preset slow \
  -b:v 16M -maxrate 20M -bufsize 32M -g 30 -bf 0 \
  -colorspace bt709 -color_primaries bt709 -color_trc bt709 -color_range tv \
  -c:a aac_at -b:a 192k -ar 48000 \
  -shortest -movflags +faststart -map_metadata -1 \
  -metadata title='实事求是' \
  -metadata comment="$NOTE" \
  -metadata description="$NOTE" \
  -metadata:s:v:0 handler_name='Rendered video (not camera footage)' \
  -metadata:s:a:0 handler_name="$( [ "${MUSIC:-1}" = 1 ] && echo 'Synthesised audio + scripted piano score' || echo 'Synthesised audio')" \
  "$OUT"
echo "exit=$? out=$OUT"
